-- Spark Feedback: call-script customer list (100 dummy customers).
-- call_script holds a combo of tags, e.g. [FTF][Shield][NC][NONENG].
-- Tags: FTF NFTF VC VCTI TI Cash ILP Shield NC Roadshow Rental Shared Offshore NONENG 'TIER 1' 'TIER 2'
-- All data is fictitious. Run: psql -U spark -d spark -f callscript_customer.sql

CREATE SCHEMA IF NOT EXISTS feedback;
DROP TABLE IF EXISTS feedback.callscript_customer;
CREATE TABLE feedback.callscript_customer (  s_no INTEGER PRIMARY KEY,
  batch VARCHAR(20),
  call_script VARCHAR(120) NOT NULL,
  financial_soundness_chk VARCHAR(5),
  vc_lite VARCHAR(5),
  alert VARCHAR(100),
  ph_sn INTEGER,
  fhr_sn INTEGER,
  fhr_id VARCHAR(20),
  freelook_date DATE,
  fsc1_channel VARCHAR(20),
  fsc1_code VARCHAR(20),
  fsc1_name VARCHAR(80),
  fsc1_agency_name VARCHAR(80),
  fsc1_email VARCHAR(100),
  fsc1_leader_name VARCHAR(80),
  fsc1_leader_email VARCHAR(100),
  fsc2_channel VARCHAR(20),
  fsc2_code VARCHAR(20),
  fsc2_name VARCHAR(80),
  fsc2_agency_name VARCHAR(80),
  fsc2_email VARCHAR(100),
  fsc2_leader_name VARCHAR(80),
  fsc2_leader_email VARCHAR(100),
  owner_nric VARCHAR(12),
  owner_name VARCHAR(80),
  owner_gender CHAR(1),
  owner_contact_mobile VARCHAR(20),
  owner_contact_home VARCHAR(20),
  owner_contact_office VARCHAR(20),
  insured_name VARCHAR(80),
  trusted_individual_name VARCHAR(80),
  trusted_individual_contact_no VARCHAR(20),
  eapp_reference_no VARCHAR(30),
  proposal_num VARCHAR(15),
  plan_name VARCHAR(80),
  plan_type VARCHAR(30),
  policy_status VARCHAR(30),
  backdated VARCHAR(3),
  scope_of_application VARCHAR(30),
  offshore_introducter VARCHAR(3),
  first_issue_date DATE,
  submission_date DATE,
  remarks TEXT,
  call_status VARCHAR(30),
  date_time_1 TIMESTAMP,
  date_time_2 TIMESTAMP,
  date_time_3 TIMESTAMP,
  tme_remarks TEXT,
  fl_remark TEXT,
  bq_remarks TEXT,
  invalid_no VARCHAR(3),
  is_nftf_ind CHAR(1),
  isremotesign CHAR(1),
  is_trusted_individual_ind CHAR(1),
  vcindicator CHAR(1),
  rental_address_indicator CHAR(1),
  accredited_investor CHAR(1),
  signed_in_singapore CHAR(1),
  citizenship VARCHAR(30),
  country_cd CHAR(2),
  surndr_company_name VARCHAR(80),
  surndr_type_of_product VARCHAR(40),
  surndr_product_policy_number VARCHAR(20),
  surndr_inception_date DATE,
  surndr_benefits_provided VARCHAR(120),
  surndr_surrender_date DATE,
  replace_company_name VARCHAR(80),
  replace_type_of_product VARCHAR(40),
  replace_product_policy_number VARCHAR(20),
  replace_inception_date DATE,
  replace_benefits_provided VARCHAR(120),
  replaced_dip_surrenderdate DATE,
  is_dclrn_advise_rple_ind CHAR(1),
  is_dclrn_surrender_ind CHAR(1),
  is_dclrn_replace_ind CHAR(1),
  hospitalised_inthe_last_threeyears CHAR(1),
  receiving_additinal_premium CHAR(1),
  existing_integrated_plan CHAR(1),
  leaderispresentforappointment CHAR(1),
  fhr_sign_dt DATE,
  ispos CHAR(1),
  ismeetingheldeclared CHAR(1),
  english_proficient_ind CHAR(1),
  english_spoken_ind CHAR(1),
  english_written_ind CHAR(1),
  english_spoken_non_prof_ind CHAR(1),
  cash_value_ind CHAR(1),
  single_exceed_50_percent CHAR(1),
  medisave_exceed_50_percent CHAR(1),
  medisave_exceed_100_percent CHAR(1),
  regular_exceed_50_percent CHAR(1),
  regular_exceed_100_percent CHAR(1),
  tier VARCHAR(10),
  pct NUMERIC(5,2),
  noneng VARCHAR(30)
);

CREATE INDEX idx_callscript_customer_script ON feedback.callscript_customer (call_script);

COMMENT ON COLUMN feedback.callscript_customer.call_script IS 'Combo of call-script tags, e.g. [FTF][Shield][NC][NONENG]';

