-- Link the 7 mock sign-in policies to call-script rows (the app looks a customer up by proposal_num = policy number).
-- NONENG customers (L234567891, M345678912, M456789123) get the English-comfort question; the others skip it.
-- NFTF + VCTI customers (L123456789) get the sales-meeting presence questions.
-- FTF + VC (M789123456) get all the FTF/VC questions; FTF + VCTI (M456789123) skip the trusted-individual ones.
-- Roadshow: B567891234. ILP + TIER 1: M789123456. Rental + Shield: L678912345.
-- Rental customers (L678912345, M456789123) get the door-knock question.
UPDATE feedback.callscript_customer c SET
  proposal_num = v.policy_no, call_script = v.script,
  is_nftf_ind = CASE WHEN v.script LIKE '[NFTF]%' THEN 'Y' ELSE 'N' END,
  noneng = CASE WHEN v.script LIKE '%[NONENG]%' THEN v.lang END,
  english_proficient_ind = CASE WHEN v.script LIKE '%[NONENG]%' THEN 'N' ELSE 'Y' END,
  english_spoken_ind = CASE WHEN v.script LIKE '%[NONENG]%' THEN 'N' ELSE 'Y' END,
  english_written_ind = CASE WHEN v.script LIKE '%[NONENG]%' THEN 'N' ELSE 'Y' END,
  english_spoken_non_prof_ind = CASE WHEN v.script LIKE '%[NONENG]%' THEN 'Y' ELSE 'N' END
FROM (VALUES
  (1, 'L123456789', '[NFTF][VCTI]', NULL),
  (2, 'L234567891', '[NFTF][NONENG]', 'Malay'),
  (3, 'L678912345', '[NFTF][Shield][Rental]', NULL),
  (4, 'M345678912', '[FTF][NONENG]', 'Mandarin'),
  (5, 'M456789123', '[FTF][VCTI][NC][NONENG][Rental]', 'Tamil'),
  (6, 'M789123456', '[FTF][VC][ILP][TIER 1]', NULL),
  (7, 'B567891234', '[NFTF][Roadshow]', NULL)
) AS v(s_no, policy_no, script, lang)
WHERE c.s_no = v.s_no;
